<?php
declare(strict_types=1);
$dataFile=__DIR__.'/data/data.json';
$data=is_file($dataFile)?json_decode((string)file_get_contents($dataFile),true):[];
if(!is_array($data)){$data=[];}
function esc($v): string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function valid_url($v): bool{return is_string($v)&&$v!==''&&$v!=='#'&&filter_var($v,FILTER_VALIDATE_URL)!==false;}
$id=trim((string)($_GET['id']??'homepage'),'/'); if($id===''){$id='homepage';}
$page=(isset($data[$id])&&is_array($data[$id]))?$data[$id]:null;
$found=$page!==null;
if(!$found){http_response_code(404);header('X-Robots-Tag: noindex, nofollow');$page=['title'=>'Halaman tidak ditemukan','meta_description'=>'Halaman tidak ditemukan','h1'=>'Halaman tidak ditemukan','content_html'=>'<p>Konten yang diminta tidak tersedia.</p>'];}
$home=(isset($data['homepage'])&&is_array($data['homepage']))?$data['homepage']:[];
$title=(string)($page['title']??'');$description=(string)($page['meta_description']??'');$h1=(string)($page['h1']??$title);$content=(string)($page['content_html']??'');
$site=(string)($home['keyword']??'Portal Keluarga');$logo=(string)($home['logo_src']??'');$favicon=(string)($home['favicon_src']??'');
$banner=(string)($page['image_src']??($page['banner_src']??($home['banner_src']??'')));$cta=(string)($home['cta']??'#');
$canonical=(string)($page['canonical_url']??'');if(!valid_url($canonical)){$canonical='https://example.test/'.($id==='homepage'?'':rawurlencode($id).'/');}
$amp=(string)($page['amp_url']??'');$gsc=(string)($home['gsc_token']??'');$robots=(!$found||!empty($page['noindex']))?'noindex, nofollow':'index, follow';
$ampLinks=valid_url($amp)?'<link rel="amphtml" href="'.esc($amp).'">'."\n".'<link rel="alternate" href="'.esc($canonical).'">'."\n".'<link rel="alternate" hreflang="id-ID" href="'.esc($amp).'">'."\n".'<link rel="alternate" hreflang="id" href="'.esc($amp).'">'."\n".'<link rel="alternate" hreflang="en" href="'.esc($amp).'">'."\n".'<link rel="alternate" hreflang="x-default" href="'.esc($amp).'">':'';
$gscTag=$gsc!==''?'<meta name="google-site-verification" content="'.esc($gsc).'">':'';
$html=base64_decode('',true);if($html===false){http_response_code(500);exit('Template payload tidak valid.');}
$replace=['%%TITLE%%'=>esc($title),'%%DESCRIPTION%%'=>esc($description),'%%H1%%'=>esc($h1),'%%CONTENT%%'=>$content,'%%SITE%%'=>esc($site),'%%LOGO%%'=>esc($logo),'%%FAVICON%%'=>esc($favicon),'%%BANNER%%'=>esc($banner),'%%CTA%%'=>esc($cta),'%%CANONICAL%%'=>esc($canonical),'%%ROBOTS%%'=>$robots,'%%GSC%%'=>$gscTag,'%%AMP_LINKS%%'=>$ampLinks];
echo strtr($html,$replace);
